import os, sqlite3
from datetime import datetime
from functools import wraps
from flask import Flask, request, redirect, url_for, flash, session, render_template_string

BASE_DIR=os.path.abspath(os.path.dirname(__file__))
DB_PATH=os.path.join(BASE_DIR,'high_desert_fire.db')
app=Flask(__name__)
app.secret_key=os.environ.get('SECRET_KEY','dev-change-me')
ADMIN_PASSWORD=os.environ.get('ADMIN_PASSWORD','change-this-password')
AREAS=['Yucca Valley','Joshua Tree','Twentynine Palms','Morongo Valley','Desert Hot Springs','Indio']
SERVICES=[('Fire Watch','Available','On-site fire watch coverage for qualifying properties, construction sites, impairments, and special situations, subject to applicable requirements.'),('Portable Fire Extinguisher Service','Planned','Inspection, maintenance, recharge, replacement, tagging, and compliance tracking after required California licensing is in place.'),('Commercial Safety Inspections','Planned','Recurring site safety checks, documentation, deficiency tracking, and customer asset records where legally permitted.'),('Kitchen Suppression Systems','Future','Future commercial kitchen suppression inspection and service division once properly licensed and staffed.'),('Fire Sprinkler Service','Future','Future sprinkler inspection, maintenance, repair, and installation services with appropriately licensed personnel.')]

def db():
    c=sqlite3.connect(DB_PATH); c.row_factory=sqlite3.Row; return c

def init_db():
    c=db(); c.executescript('''
    CREATE TABLE IF NOT EXISTS service_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT NOT NULL,business_name TEXT,contact_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,service_type TEXT NOT NULL,location TEXT NOT NULL,address TEXT,urgency TEXT,details TEXT,status TEXT NOT NULL DEFAULT 'New');
    CREATE TABLE IF NOT EXISTS job_applications(id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT NOT NULL,full_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,city TEXT NOT NULL,position TEXT NOT NULL,guard_card TEXT,emt TEXT,fire_experience TEXT,availability TEXT,notes TEXT,status TEXT NOT NULL DEFAULT 'New');
    '''); c.commit(); c.close()

STYLE='''
:root{--bg:#0a0d10;--paper:#f4f1ea;--ink:#171a1f;--muted:#66707b;--red:#e84d32;--gold:#f5a623;--line:#d9d4ca}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;background:var(--paper);color:var(--ink)}a{color:inherit}.wrap{width:min(1160px,calc(100% - 32px));margin:auto}.header{position:sticky;top:0;z-index:10;background:rgba(10,13,16,.97);color:white;border-bottom:1px solid #242a31}.nav{min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{text-decoration:none;display:flex;align-items:center;gap:12px}.mark{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;font-weight:900;background:linear-gradient(135deg,var(--red),var(--gold))}.brand small{display:block;color:#aab2bd}.navlinks{display:flex;gap:18px;align-items:center}.navlinks a{text-decoration:none}.cta,.btn{display:inline-block;border:0;border-radius:12px;padding:13px 18px;font-weight:800;text-decoration:none;cursor:pointer}.primary{background:linear-gradient(135deg,var(--red),#ff6d3f);color:white}.secondary{border:1px solid #555;background:transparent;color:white}.hero{background:radial-gradient(circle at 80% 20%,#372018 0,#101418 42%,#090b0e 100%);color:white;padding:84px 0}.hero-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:52px;align-items:center}h1{font-size:clamp(2.7rem,6vw,5.6rem);line-height:.95;margin:12px 0 22px;letter-spacing:-.05em}h2{font-size:clamp(2rem,4vw,3.4rem);margin:8px 0 26px;letter-spacing:-.04em}.lead{font-size:1.15rem;color:#c8d0d8;max-width:720px;line-height:1.7}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-weight:900;color:#f6a52f;font-size:.8rem}.hero-card,.card,.form-shell,.login-box,.success-box,.table-card{background:white;border:1px solid var(--line);border-radius:20px;padding:24px;box-shadow:0 12px 40px rgba(0,0,0,.08)}.hero-card{background:#14191f;color:white;border-color:#2c333b}.hero-card .shield{width:88px;height:88px;border-radius:24px;background:linear-gradient(135deg,var(--red),var(--gold));display:grid;place-items:center;font-weight:1000;font-size:1.7rem}.section{padding:76px 0}.dark{background:#11161b;color:white}.card-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card p{color:var(--muted);line-height:1.6}.badge{display:inline-block;padding:6px 10px;border-radius:999px;font-size:.76rem;font-weight:900;background:#ece9e2}.badge.Available{background:#dff5e6;color:#176234}.badge.Planned{background:#fff0c7;color:#775300}.badge.Future{background:#e6e9ee;color:#4b5563}.actions{display:flex;gap:12px;margin:28px 0}.trust{display:flex;gap:18px;flex-wrap:wrap;color:#b6c0ca;font-size:.92rem}.page-head{padding:62px 0 28px;background:#11161b;color:white}.page-head h1{font-size:clamp(2.5rem,5vw,4.5rem)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.form-grid label{display:flex;flex-direction:column;gap:8px;font-weight:800}.span2{grid-column:1/-1}input,select,textarea{width:100%;padding:13px 14px;border:1px solid #cfc9bf;border-radius:10px;background:#fff;font:inherit}textarea{resize:vertical}.flash{margin:16px auto;padding:12px 16px;border-radius:10px;background:#ffe5e1}.footer{background:#090c0f;color:#c7cfd7;padding:48px 0 28px;margin-top:40px}.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.9rem}th,td{text-align:left;padding:10px;border-bottom:1px solid #ddd;vertical-align:top}.admin-head{display:flex;align-items:center;justify-content:space-between;gap:20px}.note{color:#6b7280;font-size:.9rem}.warning{background:#fff2cc;border:1px solid #edd37a;padding:12px;border-radius:10px;margin:18px 0}@media(max-width:820px){.hero-grid,.card-grid,.footer-grid,.form-grid{grid-template-columns:1fr}.span2{grid-column:auto}.nav{align-items:flex-start;padding:14px 0;flex-direction:column}.navlinks{flex-wrap:wrap;padding-bottom:12px}.hero{padding:56px 0}h1{font-size:3.2rem}}
'''
BASE='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ title or 'High Desert Fire Protection & Safety' }}</title><style>{{ style|safe }}</style></head><body><header class="header"><div class="wrap nav"><a class="brand" href="/"><span class="mark">HDF</span><span><b>High Desert Fire</b><small>Protection & Safety</small></span></a><nav class="navlinks"><a href="/services">Services</a><a href="/request-service">Request Service</a><a href="/apply">Careers</a><a class="cta primary" href="/request-service">Get a Quote</a></nav></div></header>{% with msgs=get_flashed_messages() %}{% if msgs %}<div class="wrap">{% for m in msgs %}<div class="flash">{{m}}</div>{% endfor %}</div>{% endif %}{% endwith %}{{ body|safe }}<footer class="footer"><div class="wrap footer-grid"><div><b>High Desert Fire Protection & Safety</b><p>Serving the Morongo Basin and Coachella Valley.</p></div><div><b>Service Areas</b><p>{{ areas|join(' • ') }}</p></div><div><b>Compliance Notice</b><p>Services requiring California licensing are not offered until required licenses and qualified personnel are in place.</p></div></div></footer></body></html>'''

def page(body,title=None,**ctx):
    rendered=render_template_string(body,**ctx)
    return render_template_string(BASE,body=rendered,title=title,style=STYLE,areas=AREAS)

@app.route('/')
def home():
    return page('''<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">High Desert • Coachella Valley</span><h1>Fire safety coverage built for desert businesses.</h1><p class="lead">Professional fire watch coordination, commercial safety support, and a growing fire-protection service platform for local businesses, property managers, contractors, and facilities.</p><div class="actions"><a class="btn primary" href="/request-service">Request Service</a><a class="btn secondary" href="/services">View Services</a></div><div class="trust"><span>24/7 request intake</span><span>Commercial focused</span><span>Digital records</span></div></div><div class="hero-card"><div class="shield">HDF</div><h3>High Desert Fire Protection & Safety</h3><p>Local response. Clear documentation. Built to grow into a complete recurring fire-protection service company.</p><p><b>Now building:</b> fire watch + commercial account platform</p></div></div></section><section class="section"><div class="wrap"><span class="eyebrow">Service Platform</span><h2>One company, multiple fire-safety divisions.</h2><div class="card-grid">{% for n,s,d in services %}<article class="card"><span class="badge {{s}}">{{s}}</span><h3>{{n}}</h3><p>{{d}}</p></article>{% endfor %}</div></div></section><section class="section dark"><div class="wrap"><span class="eyebrow">Commercial Accounts</span><h2>Built around recurring service.</h2><p class="lead">The application is being structured for customer records, inspections, fire-watch logs, equipment assets, service reminders, quotes, jobs, and eventually invoicing.</p></div></section>''',services=SERVICES)

@app.route('/services')
def services():
    return page('''<section class="page-head"><div class="wrap"><span class="eyebrow">Services</span><h1>Built in stages, with compliance first.</h1><p class="lead">Fire watch is the launch division while regulated extinguisher, sprinkler, suppression, and alarm work is activated only after required licensing is secured.</p></div></section><section class="section"><div class="wrap card-grid">{% for n,s,d in services %}<article class="card"><span class="badge {{s}}">{{s}}</span><h3>{{n}}</h3><p>{{d}}</p></article>{% endfor %}</div></section>''',services=SERVICES)

@app.route('/request-service',methods=['GET','POST'])
def request_service():
    if request.method=='POST':
        req=['contact_name','phone','email','service_type','location']
        if any(not request.form.get(k,'').strip() for k in req): flash('Please complete all required fields.'); return redirect(url_for('request_service'))
        c=db(); c.execute('INSERT INTO service_requests(created_at,business_name,contact_name,phone,email,service_type,location,address,urgency,details) VALUES(?,?,?,?,?,?,?,?,?,?)',(datetime.now().isoformat(timespec='seconds'),request.form.get('business_name','').strip(),request.form['contact_name'].strip(),request.form['phone'].strip(),request.form['email'].strip(),request.form['service_type'].strip(),request.form['location'].strip(),request.form.get('address','').strip(),request.form.get('urgency','').strip(),request.form.get('details','').strip())); c.commit(); c.close(); return redirect('/thanks?type=service')
    return page('''<section class="page-head"><div class="wrap"><span class="eyebrow">Customer Application</span><h1>Request service or a commercial quote.</h1></div></section><section class="section"><div class="wrap form-shell"><form method="post" class="form-grid"><label>Business / Property Name<input name="business_name"></label><label>Contact Name *<input name="contact_name" required></label><label>Phone *<input name="phone" required></label><label>Email *<input type="email" name="email" required></label><label>Service Needed *<select name="service_type" required><option value="">Select</option>{% for n,s,d in services %}<option>{{n}}</option>{% endfor %}</select></label><label>City / Area *<select name="location" required><option value="">Select</option>{% for a in areas %}<option>{{a}}</option>{% endfor %}<option>Other</option></select></label><label class="span2">Property Address<input name="address"></label><label>Urgency<select name="urgency"><option>Routine</option><option>Within 7 days</option><option>Within 48 hours</option><option>Urgent / Same day request</option></select></label><label class="span2">Describe the job<textarea name="details" rows="6"></textarea></label><div class="span2"><button class="btn primary">Submit Service Request</button></div></form></div></section>''',services=SERVICES,areas=AREAS,title='Request Service | High Desert Fire')

@app.route('/apply',methods=['GET','POST'])
def apply():
    if request.method=='POST':
        req=['full_name','phone','email','city','position']
        if any(not request.form.get(k,'').strip() for k in req): flash('Please complete all required fields.'); return redirect(url_for('apply'))
        c=db(); c.execute('INSERT INTO job_applications(created_at,full_name,phone,email,city,position,guard_card,emt,fire_experience,availability,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)',(datetime.now().isoformat(timespec='seconds'),request.form['full_name'].strip(),request.form['phone'].strip(),request.form['email'].strip(),request.form['city'].strip(),request.form['position'].strip(),request.form.get('guard_card',''),request.form.get('emt',''),request.form.get('fire_experience',''),request.form.get('availability',''),request.form.get('notes',''))); c.commit(); c.close(); return redirect('/thanks?type=job')
    return page('''<section class="page-head"><div class="wrap"><span class="eyebrow">Employment Application</span><h1>Apply to join the future team.</h1></div></section><section class="section"><div class="wrap form-shell"><form method="post" class="form-grid"><label>Full Name *<input name="full_name" required></label><label>Phone *<input name="phone" required></label><label>Email *<input type="email" name="email" required></label><label>City *<input name="city" required></label><label>Position *<select name="position" required><option>Fire Watch</option><option>Fire Safety Technician Trainee</option><option>Inspection Support</option><option>Operations / Admin</option></select></label><label>California Guard Card?<select name="guard_card"><option>No</option><option>Yes</option><option>In progress</option></select></label><label>EMT Certification?<select name="emt"><option>No</option><option>Yes</option><option>In progress</option></select></label><label>Fire-service experience<input name="fire_experience"></label><label class="span2">Availability<textarea name="availability" rows="3"></textarea></label><label class="span2">Anything else?<textarea name="notes" rows="5"></textarea></label><div class="span2"><button class="btn primary">Submit Application</button></div></form></div></section>''',title='Careers | High Desert Fire')

@app.route('/thanks')
def thanks():
    typ=request.args.get('type','service'); msg='Your application has been added to the applicant dashboard.' if typ=='job' else 'Your service request has been added to the customer lead dashboard.'
    return page('''<section class="section"><div class="wrap success-box"><h1>Submitted successfully.</h1><p>{{msg}}</p><a class="btn primary" href="/">Back to Home</a></div></section>''',msg=msg)

def admin_required(fn):
    @wraps(fn)
    def w(*a,**k):
        if not session.get('admin'): return redirect('/admin')
        return fn(*a,**k)
    return w

@app.route('/admin',methods=['GET','POST'])
def admin():
    if request.method=='POST':
        if request.form.get('password')==ADMIN_PASSWORD: session['admin']=True; return redirect('/admin/dashboard')
        flash('Incorrect password.')
    return page('''<section class="section"><div class="wrap login-box"><h2>Owner Dashboard</h2><form method="post"><label>Password<input type="password" name="password" required></label><p><button class="btn primary">Sign In</button></p></form></div></section>''')

@app.route('/admin/dashboard')
@admin_required
def dashboard():
    c=db(); leads=c.execute('SELECT * FROM service_requests ORDER BY id DESC').fetchall(); apps=c.execute('SELECT * FROM job_applications ORDER BY id DESC').fetchall(); c.close()
    return page('''<section class="section"><div class="wrap"><div class="admin-head"><div><span class="eyebrow">Private Operations</span><h2>Owner Dashboard</h2></div><a class="btn primary" href="/admin/logout">Log Out</a></div><div class="warning">Prototype note: this first deployment uses local SQLite storage. Render free web services can replace local files during deploy/restart, so this should be moved to persistent Postgres before relying on it for permanent customer records.</div><div class="table-card"><h3>Service Requests ({{leads|length}})</h3><div class="table-wrap"><table><tr><th>Date</th><th>Business / Contact</th><th>Service</th><th>Location</th><th>Contact</th></tr>{% for r in leads %}<tr><td>{{r.created_at}}</td><td><b>{{r.business_name or '—'}}</b><br>{{r.contact_name}}</td><td>{{r.service_type}}<br><span class="note">{{r.urgency or ''}}</span></td><td>{{r.location}}<br>{{r.address or ''}}</td><td>{{r.phone}}<br>{{r.email}}<br>{{r.details or ''}}</td></tr>{% else %}<tr><td colspan="5">No requests yet.</td></tr>{% endfor %}</table></div></div><br><div class="table-card"><h3>Job Applications ({{apps|length}})</h3><div class="table-wrap"><table><tr><th>Date</th><th>Name</th><th>Position</th><th>Credentials</th><th>Contact</th></tr>{% for a in apps %}<tr><td>{{a.created_at}}</td><td><b>{{a.full_name}}</b><br>{{a.city}}</td><td>{{a.position}}</td><td>Guard: {{a.guard_card}}<br>EMT: {{a.emt}}<br>{{a.fire_experience or ''}}</td><td>{{a.phone}}<br>{{a.email}}<br>{{a.availability or ''}}<br>{{a.notes or ''}}</td></tr>{% else %}<tr><td colspan="5">No applications yet.</td></tr>{% endfor %}</table></div></div></div></section>''',leads=leads,apps=apps)

@app.route('/admin/logout')
def logout(): session.clear(); return redirect('/')
@app.route('/health')
def health(): return {'status':'ok'},200

init_db()
if __name__=='__main__': app.run(host='0.0.0.0',port=int(os.environ.get('PORT',5000)))
